def prepare():
    lang=materialize();delta=read(PROJECT/'lexical-delta.json');added=[]
    def add(key,entry,label):
        if key in delta['entries']:return
        assert key not in lang.lexicon,key
        entry.update(semanticId='lex.'+key,usageScope='later-standard',status='authored',historicalForms=[])
        delta['entries'][key]=entry;delta['glosses'][key]=label;added.append(key)
    for key,(form,label,meaning) in NAMES.items():
        add(key,dict(form=form,roman=lang.reading(form),pos='proper',meaning=meaning,
            origin='Permitted sound adaptation of a source personal or place name; no claim of a historical sound law.'),label)
    for key,(parent,label,pos,meaning) in CONTEXTS.items():
        e=deepcopy(lang.lexicon[parent]);e.update(pos=pos,meaning=meaning,origin='Reviewed contextual sense of '+parent)
        add(key,e,label)
    available={**lang.lexicon,**delta['entries']}
    for key,(parents,pos,label,meaning) in DERIVATIONS.items():
        form=''.join(available[p]['form'] for p in parents)
        if pos=='agent':form+=lang.suffix['ag'][0];pos='noun'
        add(key,dict(form=form,roman=lang.reading(form),pos=pos,meaning=meaning,
            derivationKeys=parents,origin='Authored native lexical derivation: '+' + '.join(parents)),label)
    for key,(form,label,pos,meaning) in ROOTS.items():
        if key not in delta['entries']:
            assert not any(e['form']==form for e in available.values()),('Review root homonym',key)
        add(key,dict(form=form,roman=lang.reading(form),pos=pos,meaning=meaning,
            origin='Authored short native lexical formation; motivation specified in definition, not a claimed attested historical change.'),label)
    delta['decisions'].append(dict(work='lucrece',decision='Separate father/son Tarquin and Brutus identities; native political titles, source-order numeric notation, and the distinction between reported culpability and translator endorsement.')) if added else None
    write(PROJECT/'lexical-delta.json',delta);materialize()
    print('Lucrece lexical additions:',len(added))

if __name__=='__main__':prepare()
